function seedAll() {
  let totalQuestions = 0;
  let filesUpdated = 0;

  for (const [examKey, subjects] of Object.entries(templates)) {
    const examType = examKey.toUpperCase();
    for (const [subject, diffs] of Object.entries(subjects)) {
      for (const [difficulty, sampleList] of Object.entries(diffs)) {
        const fileName = `${difficulty.toLowerCase()}.json`;
        const filePath = path.join(baseDir, examKey, subject, fileName);
        if (!fs.existsSync(path.dirname(filePath))) {
          fs.mkdirSync(path.dirname(filePath), { recursive: true });
        }

        let defaultDurationMs = 60000;
        if (fs.existsSync(filePath)) {
          const raw = fs.readFileSync(filePath, 'utf8').trim();
          if (raw.length > 0) {
            try {
              const parsed = JSON.parse(raw);
              if (parsed.meta && parsed.meta.defaultDurationMs) {
                defaultDurationMs = parsed.meta.defaultDurationMs;
              }
            } catch {
              // Ignore malformed existing file
            }
          }
        }

        const prefix = `${examType}-${subject.slice(0, 3).toUpperCase()}-${difficulty[0]}`;
        const questions = sampleList.map((item, idx) => ({
          externalId: `${prefix}-${String(idx + 1).padStart(3, '0')}`,
          subTopic: item.subTopic,
          text: formatQuestionText(item.text),
          ...(item.explanation ? { explanation: formatQuestionText(item.explanation) } : {}),
          imageUrl: null,
          options: item.options.map((opt) => formatQuestionText(opt)),
          correctOptionIndex: item.correctOptionIndex,
          ...(item.durationMs ? { durationMs: item.durationMs } : {}),
        }));

        const payload = {
          meta: {
            examType,
            subject,
            difficulty,
            defaultDurationMs,
          },
          questions,
        };

        fs.writeFileSync(filePath, JSON.stringify(payload, null, 2), 'utf8');
        totalQuestions += questions.length;
        filesUpdated += 1;
      }
    }
  }

  const interactivePath = path.join(baseDir, 'interactive.json');
  const interactivePayload = {
    meta: {
      examType: 'TYT & AYT',
      totalCount: RAW_INTERACTIVE_QUESTIONS.length,
      interactiveTypesCount: 14,
      description: 'İşler Arena 14 İnteraktif Soru Tipi Havuzu (TYT & AYT Matematik, Fizik, Kimya, Biyoloji, Türkçe)',
    },
    questions: RAW_INTERACTIVE_QUESTIONS,
  };
  fs.writeFileSync(interactivePath, JSON.stringify(interactivePayload, null, 2), 'utf8');

  console.log(
    `Seeded ${filesUpdated} question bank files (${totalQuestions} test questions + ${RAW_INTERACTIVE_QUESTIONS.length} interactive questions).`
  );
}

if (require.main === module) {
  seedAll();
}

module.exports = { seedAll };
